  // ---------- 검색 ----------
  function norm(s) {
    return String(s || '').toLowerCase().replace(/[\s.,?!~·•'"“”‘’()\[\]{}:;\-_/\\|「」『』<>…]/g, '');
  }
  function scoreTopic(t, n) {
    var sc = 0;
    (t.keys || []).forEach(function (k) {
      var nk = norm(k);
      if (nk && n.indexOf(nk) >= 0) sc += Math.min(6, 1 + nk.length);
    });
    if (t.q && n.length >= 4 && norm(t.q).indexOf(n) >= 0) sc += 4;
    return sc;
  }
  function search(q) {
    var n = norm(q);
    if (!n) return [];
    return TOPICS.map(function (t) { return { t: t, s: scoreTopic(t, n) }; })
      .filter(function (x) { return x.s > 0; })
      .sort(function (a, b) { return b.s - a.s; });
  }

  // ---------- 화면 요소 찾기 & 강조 ----------
