  function docs() {
    var list = [{ doc: document, frame: null }];
    Array.prototype.forEach.call(document.querySelectorAll('iframe'), function (f) {
      try { if (f.contentDocument && f.contentDocument.body) list.push({ doc: f.contentDocument, frame: f }); } catch (e) { /* 다른 도메인 */ }
    });
    return list;
  }
  function findTarget(spots) {
    spots = [].concat(spots || []);
    var ds = docs();
    for (var i = 0; i < spots.length; i++) {
      var sp = spots[i];
      for (var j = 0; j < ds.length; j++) {
        var d = ds[j].doc;
        var pool = Array.prototype.slice.call(d.querySelectorAll(sp.sel || 'button,a,[role=tab],[role=button],summary,label,h1,h2,h3,h4,nav'));
        if (sp.text) {
          var want = norm(sp.text);
          pool = pool.filter(function (e) { return norm(e.textContent).indexOf(want) >= 0; });
          pool.sort(function (a, b) { return a.textContent.length - b.textContent.length; });
        }
        pool = pool.filter(visible);
        if (pool.length) return { el: pool[0], frame: ds[j].frame };
      }
    }
    return null;
  }
