      'box-shadow:0 0 0 4px rgba(236,72,153,.35),0 0 24px 6px rgba(168,85,247,.55);transition:all .15s ease;animation:seonbiPulse 1s ease-in-out infinite alternate';
    var tag = document.createElement('div');
